start, end = 60917, 80117
src, tgt = 1010, 883
window_events = [ev for ev in events if start <= ev[2] <= end]
# by_source: node -> list of (t, v) sorted
by_source = {}
for u,v,t in window_events:
    by_source.setdefault(u, []).append((t,v))
for u in by_source:
    by_source[u].sort()
# initial events where u == src
initial = [(v,t) for u,v,t in window_events if u==src]
print('initial', initial)
from collections import deque
q = deque()
visited = set()
for v,t in initial:
    q.append((v,t, [(src,v,t)]))
    visited.add((v,t))
found = []
while q:
    node, time0, path = q.popleft()
    if node == tgt:
        found.append(path)
        break
    lst = by_source.get(node, [])
    # find first index with time > time0 by linear scan
    for t2, v2 in lst:
        if t2 > time0 and t2 - time0 <= 600:
            state = (v2, t2)
            if state not in visited:
                visited.add(state)
                q.append((v2, t2, path + [(node, v2, t2)]))
        # if t2 > time0+600 we can break because list sorted
        if t2 > time0 + 600:
            break
print('found_count', len(found))
if found:
    for p in found:
        for s in p:
            print(s)
else:
    print('no path')
# Also print events where node 66 is source
